   - DateTime.fromISO("0099-12-31").plus({ days: 60 }).toISODate()  -> expect 0100-03-01
   - DateTime.fromISO("0099-12-31").plus({ days: 2 }).toISODate()   -> expect 0100-01-02
   - DateTime.fromISO("0100-01-02").minus({ days: 2 }).toISODate()  -> expect 0099-12-31
   - DateTime.fromISO("0099-12-31").plus({ days: 59 }).toISODate()  -> expect 0100-02-28
